diff --git a/src/frontier_solution/strategy.cc b/src/frontier_solution/strategy.cc
index b0790e8..eb32b0c 100644
--- a/src/frontier_solution/strategy.cc
+++ b/src/frontier_solution/strategy.cc
@@ -1,9 +1,29 @@
-// Your search strategy goes here.
+// Chain search directed by the control-flow graph, after CREST's CFG-directed
+// search, with three changes that make each iteration and each solver call
+// count for more:
 //
-// This starter only restarts the program on fresh random inputs until the
-// budget is spent.  It compiles and runs, and it is a poor search: replace
-// the body of Run().  You may add files to this directory and include them
-// from here; see the task README for the rules on what this code may use.
+//  * Path prefixes are hashed.  A negation whose negated prefix was already
+//    asked for, or already seen on an executed path, is never sent again.
+//  * Every negation target (the branch a negation should take) keeps
+//    statistics.  Targets that were never feasible are skipped, targets whose
+//    executions seldom reach new code are ranked lower, and targets that got
+//    the program killed are dropped.
+//  * Targets that are still uncovered in the whole run are ranked first.
+//
+// The search runs in epochs.  An epoch starts from a fresh random input,
+// forgets which branches the epoch has covered, and follows a chain of
+// executions: from the current one it tries constraints in order of the CFG
+// distance of their opposite branch to code not yet covered in this epoch, and
+// moves on to the first execution that covers something new for the epoch.
+// After a negation that only gets closer, it keeps negating along the path
+// towards the uncovered code.  An epoch ends when the chain stops finding new
+// code.
+
+#include <algorithm>
+#include <cstdint>
+#include <cstring>
+#include <utility>
+#include <vector>

 #include "strategy/strategy_api.h"

@@ -11,18 +31,374 @@ namespace frontier {

 namespace {

-class RandomRestartSearch : public Strategy {
+inline uint64_t Mix64(uint64_t z) {
+  z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
+  z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
+  return z ^ (z >> 31);
+}
+
+// Hash of a prefix of symbolic branch decisions, extended by one decision.
+inline uint64_t Extend(uint64_t h, int branch) {
+  uint64_t k = Mix64(h * 0x100000001B3ULL + static_cast<uint32_t>(branch) + 0x9E3779B97F4A7C15ULL);
+  return k ? k : 1;
+}
+
+// Open-addressing set of 64-bit keys (0 is the empty marker).  It stops
+// growing at 2^max_log2 slots and then stops remembering new keys.
+class KeySet {
+ public:
+  KeySet() : mask_(0), size_(0), max_log2_(20) {}
+
+  void Init(int log2_capacity, int max_log2) {
+    table_.assign(static_cast<size_t>(1) << log2_capacity, 0);
+    mask_ = table_.size() - 1;
+    size_ = 0;
+    max_log2_ = max_log2;
+  }
+
+  bool Contains(uint64_t key) const {
+    size_t i = static_cast<size_t>(key) & mask_;
+    while (table_[i]) {
+      if (table_[i] == key) return true;
+      i = (i + 1) & mask_;
+    }
+    return false;
+  }
+
+  void Insert(uint64_t key) {
+    if (2 * (size_ + 1) > table_.size()) {
+      if (table_.size() >= (static_cast<size_t>(1) << max_log2_)) {
+        if (4 * (size_ + 1) > 3 * table_.size()) return;
+      } else {
+        Grow();
+      }
+    }
+    size_t i = static_cast<size_t>(key) & mask_;
+    while (table_[i]) {
+      if (table_[i] == key) return;
+      i = (i + 1) & mask_;
+    }
+    table_[i] = key;
+    size_++;
+  }
+
+ private:
+  void Grow() {
+    std::vector<uint64_t> old;
+    old.swap(table_);
+    table_.assign(old.size() * 2, 0);
+    mask_ = table_.size() - 1;
+    for (size_t k = 0; k < old.size(); k++) {
+      uint64_t key = old[k];
+      if (!key) continue;
+      size_t i = static_cast<size_t>(key) & mask_;
+      while (table_[i]) i = (i + 1) & mask_;
+      table_[i] = key;
+    }
+  }
+
+  std::vector<uint64_t> table_;
+  size_t mask_;
+  size_t size_;
+  int max_log2_;
+};
+
+const int kInfDist = 10000;
+
+// Feasible negations from one chain head that may find nothing new before
+// the epoch ends.
+const int kItersPerHead = 30;
+// A target infeasible this many times, and never feasible, is only retried
+// with probability 1 / (number of infeasible attempts).
+const int kSkipInfeasible = 3;
+// A target that got the program killed this often is not tried again.
+const int kMaxKills = 2;
+// Ranking bonus of a target that no execution of the run has covered yet.
+const float kUncoveredBonus = 2.0f;
+// Ranking penalty, scaled by the share of a target's feasible negations that
+// found nothing new.
+const float kBarrenWeight = 2.0f;
+
+struct Scored {
+  uint32_t k;    // constraint index
+  float score;   // ranking key, lower first
+  float base;    // ranking key without the bonus for uncovered targets
+  int seen;      // earlier occurrences of the same target in this ranking
+};
+
+class ChainSearch : public Strategy {
  public:
   virtual void Run(Host& host) {
+    h_ = &host;
+    p_ = &host.program();
+    Init();
+    int n = p_->num_branch_ids;
     while (true) {
-      const Execution* ex = host.Restart();
-      host.Release(ex);
+      cov_.assign(n, 0);
+      ncov_ = 0;
+      const Execution* ex = h_->Restart();
+      Observe(ex);
+      if (Update(ex)) Dist();
+      const Execution* succ = NULL;
+      while ((succ = DoSearch(kItersPerHead, ex)) != NULL) {
+        h_->Release(ex);
+        Dist();
+        ex = succ;
+      }
+      h_->Release(ex);
+    }
+  }
+
+ private:
+  void Init() {
+    int n = p_->num_branch_ids;
+    rev_start_.assign(n + 1, 0);
+    for (int b = 1; b < n; b++)
+      for (size_t i = 0; i < p_->successors[b].size(); i++) rev_start_[p_->successors[b][i] + 1]++;
+    for (int b = 0; b < n; b++) rev_start_[b + 1] += rev_start_[b];
+    rev_.assign(rev_start_[n], 0);
+    std::vector<int> fill(rev_start_.begin(), rev_start_.end() - 1);
+    for (int b = 1; b < n; b++)
+      for (size_t i = 0; i < p_->successors[b].size(); i++) rev_[fill[p_->successors[b][i]]++] = b;
+    dist_.assign(n, kInfDist);
+    queue_.assign(n, 0);
+    seen_.assign(n, 0);
+    seen_stamp_.assign(n, 0);
+    stamp_ = 0;
+    att_.assign(n, 0);
+    inf_.assign(n, 0);
+    kill_.assign(n, 0);
+    ran_.assign(n, 0);
+    nov_.assign(n, 0);
+    observed_.Init(16, 23);
+    attempted_.Init(14, 22);
+  }
+
+  // Marks the branches of an execution as covered in this epoch.  Returns
+  // true when one of them was not.
+  bool Update(const Execution* e) {
+    int before = ncov_;
+    for (size_t i = 0; i < e->path.size(); i++) {
+      int b = e->path[i];
+      if (b > 0 && !cov_[b]) {
+        cov_[b] = 1;
+        ncov_++;
+      }
     }
+    return ncov_ > before;
   }
+
+  // Remembers every prefix of an executed path.
+  void Observe(const Execution* e) {
+    if (!e->completed) return;
+    uint64_t h = 0;
+    for (size_t k = 0; k < e->constraint_pos.size(); k++) {
+      h = Extend(h, e->path[e->constraint_pos[k]]);
+      observed_.Insert(h);
+    }
+  }
+
+  // keys_[k]: hash of the prefix of e with constraint k negated.
+  void NegKeys(const Execution* e) {
+    size_t nc = e->constraint_pos.size();
+    keys_.resize(nc);
+    uint64_t h = 0;
+    for (size_t k = 0; k < nc; k++) {
+      int b = e->path[e->constraint_pos[k]];
+      keys_[k] = Extend(h, p_->paired[b]);
+      h = Extend(h, b);
+    }
+  }
+
+  bool Fresh(uint64_t key) const { return !attempted_.Contains(key) && !observed_.Contains(key); }
+
+  // CFG distance of every branch to the nearest branch not covered in this
+  // epoch: breadth-first search backwards from all of those.
+  void Dist() {
+    int n = p_->num_branch_ids;
+    size_t head = 0, tail = 0;
+    for (int b = 1; b < n; b++) {
+      if (!cov_[b]) {
+        dist_[b] = 0;
+        queue_[tail++] = b;
+      } else {
+        dist_[b] = kInfDist;
+      }
+    }
+    while (head < tail) {
+      int v = queue_[head++];
+      int d = dist_[v] + 1;
+      for (int i = rev_start_[v]; i < rev_start_[v + 1]; i++) {
+        int p = rev_[i];
+        if (d < dist_[p]) {
+          dist_[p] = d;
+          queue_[tail++] = p;
+        }
+      }
+    }
+  }
+
+  // Did the new execution follow the old path up to position bidx and take
+  // the other arm there?
+  bool Predict(const Execution* o, const Execution* nw, size_t bidx) const {
+    if (!nw->completed) return false;
+    if (o->path.size() <= bidx || nw->path.size() <= bidx) return false;
+    for (size_t j = 0; j < bidx; j++)
+      if (nw->path[j] != o->path[j]) return false;
+    return nw->path[bidx] == p_->paired[o->path[bidx]];
+  }
+
+  bool Skip(int t) {
+    if (kill_[t] >= kMaxKills) return true;
+    if (inf_[t] >= kSkipInfeasible && att_[t] == inf_[t])
+      return h_->Uniform(static_cast<uint32_t>(inf_[t])) != 0;
+    return false;
+  }
+
+  const Execution* Negate(const Execution* e, size_t k, uint64_t key, int t) {
+    attempted_.Insert(key);
+    att_[t]++;
+    const Execution* r = h_->Negate(e, k);
+    if (!r) {
+      inf_[t]++;
+    } else if (!r->completed) {
+      kill_[t]++;
+    } else {
+      Observe(r);
+    }
+    return r;
+  }
+
+  // Tries the constraints of prev in ranking order.  Returns the first
+  // execution that covers something new for the epoch, or NULL once `iters`
+  // feasible attempts found nothing.
+  const Execution* DoSearch(int iters, const Execution* prev) {
+    size_t nc = prev->constraint_pos.size();
+    NegKeys(prev);
+    std::vector<uint64_t> keys = keys_;
+    std::vector<Scored> sc;
+    sc.reserve(nc);
+    for (size_t i = 0; i < nc; i++) {
+      if (!Fresh(keys[i])) continue;
+      Scored s;
+      s.k = static_cast<uint32_t>(i);
+      s.score = 0;
+      s.base = 0;
+      s.seen = 0;
+      sc.push_back(s);
+    }
+    // Random order among equal ranks; repeated targets rank lower each time.
+    for (size_t i = sc.size(); i > 1; i--) std::swap(sc[i - 1], sc[h_->Uniform(static_cast<uint32_t>(i))]);
+    stamp_++;
+    for (size_t i = 0; i < sc.size(); i++) {
+      int t = p_->paired[prev->path[prev->constraint_pos[sc[i].k]]];
+      if (seen_stamp_[t] != stamp_) {
+        seen_stamp_[t] = stamp_;
+        seen_[t] = 0;
+      }
+      sc[i].seen = seen_[t];
+      sc[i].score = static_cast<float>(dist_[t]) + static_cast<float>(seen_[t]);
+      if (ran_[t] > 0)
+        sc[i].score += kBarrenWeight * static_cast<float>(ran_[t] - nov_[t]) / static_cast<float>(ran_[t] + 2);
+      sc[i].base = sc[i].score;
+      if (!h_->covered(t)) sc[i].score -= kUncoveredBonus;
+      seen_[t]++;
+    }
+    std::stable_sort(sc.begin(), sc.end(),
+                     [](const Scored& a, const Scored& b) { return a.score < b.score; });
+    for (size_t i = 0; i < sc.size(); i++) {
+      if (iters <= 0 || sc[i].base > kInfDist + 0.5f) return NULL;
+      if (!Fresh(keys[sc[i].k])) continue;
+      size_t bidx = prev->constraint_pos[sc[i].k];
+      int t = p_->paired[prev->path[bidx]];
+      if (Skip(t)) continue;
+      const Execution* cur = Negate(prev, sc[i].k, keys[sc[i].k], t);
+      if (!cur) continue;
+      iters--;
+      bool found = Update(cur);
+      bool mispredicted = !Predict(prev, cur, bidx);
+      ran_[t]++;
+      if (found) {
+        nov_[t]++;
+        return cur;
+      }
+      if (mispredicted) {
+        h_->Release(cur);
+        continue;
+      }
+      if (dist_[t] > 0 && dist_[t] < kInfDist) {
+        const Execution* s = AlongCfg(bidx, dist_[t] + sc[i].seen - 1, cur);
+        if (s) return s;
+        continue;
+      }
+      h_->Release(cur);
+    }
+    return NULL;
+  }
+
+  // ex went to path position i on purpose and is still max_dist + 1 away from
+  // new code.  Negates, further along its path, branches whose other arm is
+  // closer, until something new is covered (returned) or the walk fails
+  // (NULL).  Takes ownership of ex.
+  const Execution* AlongCfg(size_t i, int max_dist, const Execution* ex) {
+    while (true) {
+      const std::vector<uint32_t>& cp = ex->constraint_pos;
+      NegKeys(ex);
+      size_t k = std::upper_bound(cp.begin(), cp.end(), static_cast<uint32_t>(i)) - cp.begin();
+      bool progressed = false;
+      for (; k < cp.size(); k++) {
+        int b = ex->path[cp[k]];
+        int pb = p_->paired[b];
+        if (dist_[pb] > max_dist) continue;
+        if (dist_[b] <= dist_[pb]) continue;
+        if (!Fresh(keys_[k])) continue;
+        if (Skip(pb)) continue;
+        const Execution* cur = Negate(ex, k, keys_[k], pb);
+        if (!cur) {
+          h_->Release(ex);
+          return NULL;
+        }
+        if (Update(cur)) {
+          h_->Release(ex);
+          return cur;
+        }
+        if (!Predict(ex, cur, cp[k]) || dist_[pb] == 0) {
+          h_->Release(cur);
+          h_->Release(ex);
+          return NULL;
+        }
+        size_t pos = cp[k];
+        max_dist = dist_[pb] - 1;
+        h_->Release(ex);
+        ex = cur;
+        i = pos;
+        progressed = true;
+        break;
+      }
+      if (!progressed) {
+        h_->Release(ex);
+        return NULL;
+      }
+    }
+  }
+
+  Host* h_;
+  const Program* p_;
+  std::vector<int> rev_start_, rev_;  // reversed CFG, compressed rows
+  std::vector<int> dist_, queue_;
+  std::vector<char> cov_;  // covered in this epoch
+  int ncov_;
+  std::vector<int> seen_, seen_stamp_;
+  int stamp_;
+  // Per negation target: attempts, infeasible attempts, killed launches,
+  // feasible negations from a chain head, and those that found new code.
+  std::vector<int> att_, inf_, kill_, ran_, nov_;
+  std::vector<uint64_t> keys_;
+  KeySet observed_, attempted_;
 };

 }  // namespace

-Strategy* MakeStrategy() { return new RandomRestartSearch(); }
+Strategy* MakeStrategy() { return new ChainSearch(); }

 }  // namespace frontier
